from collections import defaultdict

students = [("山田", "B"), ("佐藤", "A"), ("鈴木", "A"), ("伊藤", "B"), ("田中", "A")]

def group_by_class(students):
    groups = defaultdict(list)
    for name, cls in students:
        groups[cls].append(name)
    return dict(groups)

print(group_by_class(students))

